import { useEffect, useRef, useState } from "react";

/**
 * Travelpayouts hotel-search embeds generated by the publisher.
 * Do not rewrite the URLs: campaign, promo, style, project, and shmarker
 * parameters are intentionally preserved byte-for-byte.
 */
export const hotelSearchWidgets = [
  {
    id: "agoda",
    title: "Search hotels with Agoda",
    scriptUrl: "https://tpwgt.com/content?trs=406243&shmarker=622032.accommodation_hub_widget&locale=en&default_destination=Jerusalem%2C%20Israel&powered_by=false&primary_override=%235392F9&color_button=%235392F9&color_icons=%235392F9&dark=%23262626&color_border=%235392F9&color_focused=%2332a8dd&border_radius=5&no_labels=&plain=false&promo_id=8303&campaign_id=104",
  },
  {
    id: "booking",
    title: "Search hotels with Booking.com",
    scriptUrl: "https://tpwgt.com/content?trs=406243&shmarker=622032.accommodation_hub_widget&locale=en-us&powered_by=false&campaign_id=84&promo_id=9240",
  },
] as const;

function HotelSearchWidget({ widget, visible }: {
  widget: (typeof hotelSearchWidgets)[number];
  visible: boolean;
}) {
  const mountRef = useRef<HTMLDivElement>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    const mount = mountRef.current;
    if (!visible || !mount) return;

    const script = document.createElement("script");
    script.src = widget.scriptUrl;
    script.async = true;
    script.charset = "utf-8";
    script.onerror = () => setFailed(true);
    // Third-party widgets own the children of this element, not React.
    mount.appendChild(script);

    return () => {
      script.onerror = null;
      mount.replaceChildren();
    };
  }, [visible, widget.scriptUrl]);

  return (
    <div className="min-w-0 rounded-2xl border bg-card p-4 sm:p-6" data-testid={`${widget.id}-hotel-search-widget`}>
      <h3 className="text-lg font-semibold sm:text-xl">{widget.title}</h3>
      <div
        ref={mountRef}
        className="mt-4 min-h-52 min-w-0 max-w-full overflow-x-auto [&_iframe]:max-w-full"
        aria-label={widget.title}
        data-testid={`${widget.id}-hotel-widget-mount`}
      />
      {failed && <p role="status" className="mt-2 text-sm text-muted-foreground">
        This search is temporarily unavailable. You can still explore the hotel guides above.
      </p>}
    </div>
  );
}

/**
 * Keep a separate viewport observer for each placement. Booking appears after
 * the hotel-style cards; Agoda remains after the FAQ. The external scripts are
 * still inserted only when their respective section approaches the viewport.
 */
export function TravelpayoutsHotelWidget({ provider }: {
  provider: (typeof hotelSearchWidgets)[number]["id"];
}) {
  const sectionRef = useRef<HTMLElement>(null);
  const [visible, setVisible] = useState(false);
  const widget = hotelSearchWidgets.find((item) => item.id === provider)!;

  useEffect(() => {
    const section = sectionRef.current;
    if (!section || visible) return;

    if (!("IntersectionObserver" in window)) {
      setVisible(true);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "500px 0px", threshold: 0 },
    );
    observer.observe(section);
    return () => observer.disconnect();
  }, [visible]);

  const isBooking = provider === "booking";
  const sectionId = isBooking ? "hotel-search-booking" : "hotel-search-widgets";
  const headingId = isBooking ? "hotel-search-booking-h" : "hotel-search-widgets-h";

  return (
    <section
      ref={sectionRef}
      id={sectionId}
      aria-labelledby={headingId}
      className="mt-10 scroll-mt-24"
      data-testid={sectionId}
    >
      <h2 id={headingId} className="text-2xl font-semibold">
        {isBooking ? "Search hotels in Israel" : "More hotel search options"}
      </h2>
      <div className="mt-4 min-w-0">
        <HotelSearchWidget widget={widget} visible={visible} />
      </div>
    </section>
  );
}
